raw:
{
  "spells": [
    {
      "id": "spell_fire_01",
      "theory": "火星术在指尖与火绒之间架起一道极短的魔力通路，使干火绒中的细小纤维在接触点同时升温。湿柴因水分吸热，活物因体液阻隔，都无法达到燃点；施术者只需将魔力沿着通路送入，不必持续维持，点燃后通路自行消散。若火绒受潮，通路会被水汽截断，魔力退回指尖。",
      "casting": "伸出一指，在火绒上方划一道短弧，同时将魔力沿指尖压入火绒。弧线收尾时，火绒应冒出第一缕烟。",
      "failure": "若弧线过宽，魔力散入空气，火绒只微微发热而不起火。若指尖停顿过久，火绒可能烧成焦黑小洞，却未引燃周围纤维，留下刺鼻气味。",
      "counters": [
        "用湿布覆盖火绒，水汽会截断魔力通路。",
        "将火绒放入铁盒并合盖，闷熄接触点火焰。"
      ],
      "socialConsequences": "河谷乡约允许在自家灶前或篝火处使用，但若在公共柴堆旁随意施放，可能被视作疏忽。城镇公会更看重是否在指定点火区操作，以免引燃货栈。港口搬运工依赖它点燃防风灯，但若火星溅到帆布，货主会要求赔偿。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时火星只燃起一缕烟，需再试一次。",
        "熟练后能稳定点着干燥火绒，不烧焦手指。",
        "更熟练可控制火星只落在指定火绒上，不溅开。",
        "高熟练度使点燃几乎一次成功，仍只作用于干火绒。"
      ]
    },
    {
      "id": "spell_fire_02",
      "theory": "暖掌术把魔力均匀铺在掌心与指腹，使接触面缓慢升温，热量通过皮肤和接触物传导。魔力不会在体内积聚，而是不断流向所触之物，因此揉面时面团会逐渐变温，但接触者不会感到灼痛。若掌心魔力分布不均，局部可能过热，但受术者会先感到刺痛而缩手。",
      "casting": "双掌合拢搓动三次，再按在面团或器物上，同时将魔力从掌心缓缓推入接触面。",
      "failure": "魔力推送过快时，掌心会突然发烫，面团表面结出一层硬皮，内部却仍是凉的。若搓动不足，手掌只微微温热，揉面时无法让面团达到合适温度。",
      "counters": [
        "在手掌与面团间垫一块湿布，水会吸收多余热量。",
        "将面团移开并摊开，热量会自然散入空气。"
      ],
      "socialConsequences": "河谷乡约认可在自家厨房或公共烤炉旁使用，但若在集市上替陌生人暖手，须先问明对方是否愿意。城镇面包师公会认为它有助于发酵，却禁止在公会烤炉内私自改变温度。港口船员欢迎它暖手，但若在货舱内使用，船主会担心靠近油布或干草。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时手掌温度忽高忽低，需反复搓动。",
        "熟练后能稳定保持温热，揉面时不再烫手。",
        "更熟练可让热量均匀铺开，接触者只觉温暖。",
        "高熟练度使温度几乎不波动，仍不超过温热范围。"
      ]
    },
    {
      "id": "spell_fire_03",
      "theory": "烘衣术将魔力渗入衣物纤维之间，使潮气沿着纤维缝隙向表面移动并散入空气。魔力只作用于一件衣物，帆布和仓库货物因纤维过密或体积过大而无法被覆盖。染料与纤维在正常施放时不受影响，因为魔力只推动水分子，不改变织物结构。若衣物含有金属饰件，魔力会绕开金属，只烘干周围布料。",
      "casting": "提起衣物一角，另一手在衣料上画三道平行短线，每画一道便送入一缕魔力，直到潮气从布面逸出。",
      "failure": "若短线画得太密，魔力会在布面聚成一点，使该处布料缩皱，潮气却仍留在衣内。若只画一道，魔力无法覆盖整件衣物，只有局部变干，其余部分依旧潮湿。",
      "counters": [
        "将衣物浸入清水，水会重新均匀分布并阻断魔力。",
        "把衣物挂在通风处，自然风会带走残余潮气。"
      ],
      "socialConsequences": "河谷乡约允许在自家晾衣处使用，但若在公共洗衣池旁替他人烘衣，须先征得衣物主人同意。城镇公会更关注染料是否受损，若烘坏客人的衣物，需按市价赔偿。港口船主欢迎它烘干船员衣物，但若在货舱内使用，须确保不靠近受潮的麻袋或火药桶。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时衣物只干一半，需再施一次。",
        "熟练后能一次烘干整件衣物，不伤染料。",
        "更熟练可控制潮气从衣角排出，不弄湿地面。",
        "高熟练度使烘干均匀，仍只作用于一件衣物。"
      ]
    }
  ]
}
